/**
 * Writes the optimization protocol's response shapes as one JSON Schema
 * document, `schemas/optimization-protocol.schema.json`.
 *
 * The document is checked in and regenerated by `codegen`, so CI fails when it
 * drifts from the Zod schemas in `@hashintel/petrinaut-core` that define the
 * protocol. `@local/petrinaut-python` generates its pydantic models from it.
 */

import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { z } from "zod";

import {
  petrinautOptimizationDescribeParameterSchema,
  petrinautOptimizationDescribeResultSchema,
  petrinautOptimizationEvaluateResultSchema,
  petrinautOptimizationReplicateSchema,
} from "@hashintel/petrinaut-core";

import type { ZodType } from "zod";

const packageRoot = fileURLToPath(new URL("..", import.meta.url));

/** `io: "output"` describes the serialized result the CLI writes to the wire. */
const convert = (schema: ZodType): Record<string, unknown> => {
  const json = z.toJSONSchema(schema, { io: "output" }) as Record<
    string,
    unknown
  >;
  delete json.$schema;
  return json;
};

const parameterUnion = petrinautOptimizationDescribeParameterSchema;
const [floatParameter, intParameter, booleanParameter] = parameterUnion.options;

const describeResult = convert(petrinautOptimizationDescribeResultSchema);
// The parameter union is a named definition, so generators emit one shared
// model instead of an anonymous copy inlined at each use.
(
  (describeResult.properties as Record<string, Record<string, unknown>>)
    .parameters as { items: unknown }
).items = { $ref: "#/$defs/OptimizationDescribeParameter" };

const evaluateResult = convert(petrinautOptimizationEvaluateResultSchema);
(
  (evaluateResult.properties as Record<string, Record<string, unknown>>)
    .replicates as { items?: unknown }
).items = { $ref: "#/$defs/OptimizationReplicate" };

// No root schema and no title: the document only carries `$defs`, so model
// generators emit one class per definition and nothing for the document itself.
const document = {
  $schema: "https://json-schema.org/draft/2020-12/schema",
  $defs: {
    OptimizationFloatParameter: convert(floatParameter),
    OptimizationIntParameter: convert(intParameter),
    OptimizationBooleanParameter: convert(booleanParameter),
    OptimizationDescribeParameter: {
      description: parameterUnion.meta()?.description,
      anyOf: [
        { $ref: "#/$defs/OptimizationFloatParameter" },
        { $ref: "#/$defs/OptimizationIntParameter" },
        { $ref: "#/$defs/OptimizationBooleanParameter" },
      ],
    },
    OptimizationReplicate: convert(petrinautOptimizationReplicateSchema),
    OptimizationDescribeResult: describeResult,
    OptimizationEvaluateResult: evaluateResult,
  },
};

const target = join(packageRoot, "schemas/optimization-protocol.schema.json");
await mkdir(dirname(target), { recursive: true });
await writeFile(target, `${JSON.stringify(document, null, 2)}\n`, "utf8");
process.stdout.write(`Wrote ${target}\n`);
